/*
 * output.c - code the host a compiler was built on must not change
 *
 * The expected assembly next to this was generated by a 32-bit x86 build of
 * this compiler, so a 64-bit host, or a new compiler or libc under it, has to
 * generate the same thing. What is here is what has gone wrong before: constants
 * with the high bit set, doubles held across rtl fields, and large frames.
 */

typedef struct { char c; short s; int i; unsigned b1 : 3, b2 : 5; } mixed;

static const double table[] = { 0.0, 1.0, -2.5, 3.14159265358979, 1e300, 1e-300 };
const float ftable[] = { 0.0f, 1.5f, 0.1f, -100.25f };
long long big = 0x123456789abcdefLL;
unsigned long long ubig = 0xfedcba9876543210ULL;
unsigned high = 0xf2000000u;
int neg = -1;
char text[] = "output\n";

extern int ext(int, ...);

unsigned masks(unsigned x) { return (x & 0xfffffff0u) | 0xf2000000u; }
int compare(unsigned x) { return x > 0x7fffffffu; }
int division(int x) { return x / 7 + x % 1000; }
long long wide(long long a, long long b) { return a * b + (a >> 3) - 0x100000000LL; }
long long shifted(unsigned long long a) { return a << 40 | 0xff00000000ULL; }
double doubles(double x) { return x * 2.0 + 0.5 - table[3]; }
float floats(float x) { return x * 1.5f + 0.1f; }
int truncated(double x) { return (int)x + (int)(float)x; }
double widened(int i, unsigned u) { return (double)i + (double)u; }
int pick(double a, double b) { return a < b ? 1 : a == b ? 2 : 3; }

int bits(mixed *m)
{
	m->b1 = 5;
	m->b2 = m->b1 + 1;
	return m->c + m->s + m->i + m->b2;
}

int frame(int n)
{
	char local[70000];
	int i;

	for (i = 0; i < n; i++)
		local[i * 3] = (char)i;
	return ext(n, local[n], 1.5, big);
}

int cases(int x)
{
	switch (x) {
	case 0: return 10;
	case 1: return 20;
	case 2: return 35;
	case 3: return 47;
	case 4: return 59;
	case 1000: return 0xf200;
	default: return -x;
	}
}
